"""Per-symbol migration table for the qicklab refactor (phases 3a/3b). Plain data.

One ``Entry`` per top-level statement of every legacy module under
``WorkingProjects/QM_Team/qubit_measurements/Client_modules`` at commit 0f0a51f, plus one
``<module>`` row per file (its docstring and imports, which 3a rewrites rather than moves).

Statement keys (``old_qualname``): the name for def/class/single assignments;
``a,b`` for tuple assignments; ``<main>`` for ``if __name__ == "__main__"``;
``<if:TEST>`` / ``<expr:CALL>`` for other module-level statements
(``tests.refactor.equivalence.statement_keys`` computes them).

Columns
  old_module, old_qualname   legacy dotted module + statement key
  new_module, new_name       where the symbol lives after phase 3a (verbatim body)
  kind     moved | renamed | merged | deleted | main_to_test
  phase    3a-i (whole-file move) | 3a-ii (split files) | 3b (deletions/merges)
  note     deleted: the reason (audit citation); merged: the proof ("proof: ...")
  final_module, final_name   where it ends after 3b, when different (None = same)

``merged`` in phase 3a-* means an AST-identical duplicate that a file merge forces onto
one name (the proof is machine-checked); ``merged``/``deleted`` in 3b stay verbatim at
new_module/new_name through 3a and are removed/merged by a 3b commit.
"""

from typing import NamedTuple


class Entry(NamedTuple):
    old_module: str
    old_qualname: str
    new_module: str
    new_name: str
    kind: str
    phase: str
    note: str = ""
    final_module: str | None = None
    final_name: str | None = None


